def verify_lte_detach_call_flow(messages, logger):
    """
    SPHINX_IGNORE:
    [Documentation]   FUNCTION:verify_lte_detach_callflow
    Metadata:
    | Version | Status  | Date | Author  | Change Notification |
    | 0.9 | DRAFT | 13.04.2016 | Grzegorz Kaczor  | Initial Version |
    | 0.9.1 | READY_FOR_REVIEW | 21.07.2016 | Grzegorz Kaczor | Internal_test_PASS |
    End of Metadata
    SPHINX_IGNORE

    Argument method to be used for verification of standard LTE detach call flow.
    Method first checks if a standard LTE detach is executed:
    NAS Detach request delivered in UL Information Transfer
    If not, verification is switched to LTE Detach call flow from IDLE mode

    :param messages:    messages to be used for verifying detach call flow
    :type messages:     list
    :return:            None
    """
    try:
        verify_lte_standard_detach(messages, logger)
        return
    except call_flow_exceptions.DetachVerificationException as e:
        logger.info(e)
        try:
            verify_lte_detach_from_idle_callflow(messages)
        except call_flow_exceptions.DetachException as e:
            logger.info(e)
            raise call_flow_exceptions.DetachException("Detach from IDLE mode failed")
        return
    except call_flow_exceptions.DetachException as e:
        logger.info(e)
    verify_lte_detach_from_idle_callflow(messages)
    logger.info("\nDetach from IDLE mode verification completed successfully")
    return


