def verify_lte_standard_detach(messages, logger):
    """
    SPHINX_IGNORE:
    [Documentation]   FUNCTION:verify_lte_standard_detach
    Metadata:
    | Version | Status  | Date | Author  | Change Notification |
    | 0.9 | DRAFT | 15.04.2016 | Grzegorz Kaczor  | Initial Version |
    | 0.9.1 | READY_FOR_REVIEW | 22.07.2016 | Grzegorz Kaczor | Internal_test_PASS |
    End of Metadata
    SPHINX_IGNORE

    Method checks if a standard LTE detach is executed:
    NAS Detach request delivered in UL Information Transfer

    :param messages:    messages to be used for verifying standard detach call flow
    :type messages:     list
    :return:            None
    """
    nas_index = find_index_of_last_detach_request_message(messages)
    if nas_index < 0:
        raise call_flow_exceptions.DetachVerificationException("Could not find Detach request NAS message")

    rrc_connection_setup_index = find_index_of_last_rrc_connection_request_message(messages)
    if rrc_connection_setup_index > nas_index:
        raise call_flow_exceptions.DetachException("RRCConnectionRequest message found after Detach request")

    ul_information_index = find_index_of_last_ul_information_transfer(messages)
    if ul_information_index < 0:
        raise call_flow_exceptions.DetachVerificationException(
            "Could not find Detach request UL Information Transfer message")

    logger.info("Detach verification completed successfully")
    return


